import os, json, time, urllib.request, urllib.error
base=os.environ['GALAXY_URL'].rstrip('/'); key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
hist='bbd44e69cb8906b59ddd695bf7324dc1'
fa='f9cad7b01a472135cc9426dcc045866f'; fq='f9cad7b01a472135c5d9c3dd300db890'
tool='toolshed.g2.bx.psu.edu/repos/devteam/bowtie2/bowtie2/2.5.5+galaxy0'
val=lambda x:{'values':[{'id':x,'src':'hda'}]}
inputs={
 'library': {'type':'single','__current_case__':0,'input_1':val(fq),'unaligned_file':False,'aligned_file':False},
 'reference_genome': {'source':'history','__current_case__':1,'own_file':val(fa)},
 'rg': {'rg_selector':'do_not_set','__current_case__':3},
 'analysis_type': {'analysis_type_selector':'simple','__current_case__':0,'presets':'no_presets'},
 'sam_options': {'sam_options_selector':'no','__current_case__':1},
 'save_mapping_stats': True
}
payload={'history_id':hist,'tool_id':tool,'input_format':'21.01','inputs':inputs}
req=urllib.request.Request(base+'/api/tools', data=json.dumps(payload).encode(), headers={'Content-Type':'application/json','x-api-key':key})
try:
    with urllib.request.urlopen(req, timeout=60) as r: out=json.load(r)
except urllib.error.HTTPError as e:
    print('SUBMIT_ERROR', e.code, e.read().decode()[:5000]); raise SystemExit(1)
outs=out.get('outputs',{})
if isinstance(outs, list): outmap={o.get('output_name') or o.get('name') or str(i):o.get('id') for i,o in enumerate(outs)}
else: outmap={k:v.get('id') for k,v in outs.items()}
job_ids=[j['id'] for j in out.get('jobs',[])]
print('SUBMITTED', json.dumps({'jobs':job_ids,'outputs':outmap}, indent=2))
terminal={'ok','error','deleted'}
while True:
    states={}
    all_term=True
    for jid in job_ids:
        req=urllib.request.Request(base+'/api/jobs/'+jid, headers={'x-api-key':key})
        with urllib.request.urlopen(req, timeout=30) as r: j=json.load(r)
        states[jid]=j.get('state')
        if states[jid] not in terminal: all_term=False
    if all_term: break
    time.sleep(10)
print('FINAL_STATES', json.dumps(states))
print('OUTPUTS', json.dumps(outmap, indent=2))
PY"

